import {ActivityStage3D} from './activity3d.js';
import {TempleScene} from './scene.js';
export const activityRules={
 incense:{title:'Dâng hương',icon:'♨',gesture:'up',action:'incense',instruction:'Vuốt lên để dâng một nén hương.'},
 fish:{title:'Thả cá',icon:'🐟',gesture:'down',action:'fish',instruction:'Vuốt xuống để nhẹ tay thả một chú cá.'},
 chant:{title:'Gõ mõ · Tụng kinh',icon:'📖',gesture:'tap',action:'chant',instruction:'Chạm chiếc mõ để gõ và niệm một câu.'},
 beads:{title:'Lần chuỗi bồ đề',icon:'📿',gesture:'down',action:'beads',instruction:'Vuốt từ trên xuống để kéo qua một hạt chuỗi.'},
 meditate:{title:'Ngồi thiền',icon:'🪷',gesture:'down',action:'meditate',instruction:'Vuốt xuống theo nhịp thở để an trú.'},
 sweep:{title:'Quét sân',icon:'🍂',gesture:'swipe',action:'sweep',instruction:'Vuốt qua màn hình để quét một lượt lá.'},
 meal:{title:'Ăn cơm chay',icon:'🍚',gesture:'tap',action:'meal',instruction:'Chạm bát cơm để ăn một miếng trong chánh niệm.'},
 prostrate:{title:'Quỳ lạy Phật',icon:'🙏',gesture:'down',action:'prostrate',instruction:'Vuốt xuống để chắp tay, cúi lạy Phật.'},
 sermon:{title:'Thiền & nghe pháp',icon:'🪷',gesture:'down',action:'sermon',instruction:'Vuốt xuống theo hơi thở, lắng nghe lời giảng.'}
};
export function matchesGesture(kind,start,end){const dx=end.x-start.x,dy=end.y-start.y;return kind==='tap'?Math.hypot(dx,dy)<22:kind==='down'?dy>=48&&dy>Math.abs(dx)*1.2:kind==='up'?-dy>=48&&-dy>Math.abs(dx)*1.2:Math.hypot(dx,dy)>=48;}
export class ActivityView{
 constructor({onAction,onClose,onRead}){this.onAction=onAction;this.onClose=onClose;this.onRead=onRead;this.dialog=document.querySelector('#activityScreen');this.canvas=document.querySelector('#activityCanvas');try{this.stage=new ActivityStage3D(this.canvas);}catch{const old=this.canvas;this.canvas=old.cloneNode();old.replaceWith(this.canvas);this.ctx=this.canvas.getContext('2d');}this.count=0;this.total=0;this.lastHit=-100;this.pointer=null;this.frame=0;this.scene=Object.create(TempleScene.prototype);this.scene.ctx=this.ctx;this.scene.incense=[];this.scene.ripples=[];this.scene.fish=Array.from({length:7},(_,i)=>({phase:i,speed:.4,color:['#f8c16e','#f59a6d','#fff2cc'][i%3]}));this.scene.leaves=Array.from({length:9},(_,i)=>({x:235+i%3*77,y:1000+Math.floor(i/3)*55,cleared:false}));this.scene.task={};this.scene.time=0;
 this.canvas.addEventListener('pointerdown',e=>{if(!this.id)return;e.preventDefault();this.canvas.setPointerCapture(e.pointerId);this.pointer={x:e.clientX,y:e.clientY,id:e.pointerId};this.drag=0;});this.canvas.addEventListener('pointermove',e=>{if(this.pointer?.id!==e.pointerId)return;this.drag=e.clientY-this.pointer.y;});this.canvas.addEventListener('pointerup',e=>{if(this.pointer?.id!==e.pointerId)return;const start=this.pointer;this.pointer=null;this.drag=0;if(!matchesGesture(activityRules[this.id].gesture,start,{x:e.clientX,y:e.clientY}))return;if(activityRules[this.id].gesture==='tap'){const p=this.point(e);if(Math.hypot(p.x-450,p.y-470)>210)return;}this.act();});this.canvas.addEventListener('pointercancel',()=>{this.pointer=null;this.drag=0;});
 this.canvas.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&!e.repeat){e.preventDefault();this.act();}});document.querySelector('#activityClose').onclick=()=>this.onClose();this.dialog.addEventListener('cancel',e=>{e.preventDefault();this.onClose();});document.querySelector('#activityRead').onclick=()=>this.onRead();document.querySelector('#activityRetry').onclick=()=>this.onAction({retry:true});
 }
 open(id,player){this.close();this.id=id;this.player=player;this.count=0;this.total=0;this.failed=0;this.pending=0;this.lastHit=-100;this.teaching='';this.stage?.reset();this.scene.time=0;this.scene.task={id,count:0,rotation:0,lastHit:-100,start:0};const rule=activityRules[id];document.querySelector('#activityTitle').textContent=rule.title;document.querySelector('#activityInstruction').textContent=rule.instruction;document.querySelector('#activityCount').textContent='0 thao tác';document.querySelector('#activityScore').textContent='0 XP';document.querySelector('#activityStatus').textContent='Mỗi thao tác đúng +1 XP · Chơi bao nhiêu lần tùy bạn';document.querySelector('#activityRetry').hidden=true;document.querySelector('#activityRead').hidden=id!=='sermon';document.querySelector('#activityReading').hidden=id!=='sermon';document.querySelector('#activityReading').textContent='';this.dialog.showModal();this.canvas.focus({preventScroll:true});this.lastFrame=performance.now();const loop=now=>{if(!this.id)return;this.scene.time+=Math.min(.05,(now-this.lastFrame)/1000);this.lastFrame=now;this.draw();this.frame=requestAnimationFrame(loop);};this.frame=requestAnimationFrame(loop);}
 close(){cancelAnimationFrame(this.frame);this.pointer=null;this.drag=0;this.id=null;if(this.dialog.open)this.dialog.close();}
 point(e){const r=this.canvas.getBoundingClientRect();return{x:(e.clientX-r.left-this.ox)/this.scale,y:(e.clientY-r.top-this.oy)/this.scale};}
 act(){if(!this.id)return;this.count++;this.lastHit=this.scene.time;this.scene.task.count++;this.scene.task.lastHit=this.scene.time;this.scene.task.rotation+=Math.PI/9;document.querySelector('#activityCount').textContent=this.count+' thao tác';this.onAction({retry:false});}
 status({earned,pending,failed,message}){this.total=earned;document.querySelector('#activityScore').textContent=earned+' XP';document.querySelector('#activityStatus').textContent=message||(failed?failed+' XP chưa lưu · Thử lưu lại để nhận đủ điểm':pending?'Đang lưu '+pending+' XP…':'Đã lưu · Tiếp tục tương tác để nhận thêm +1 XP');document.querySelector('#activityRetry').hidden=!failed;}
 draw(){if(this.stage){const r=this.canvas.getBoundingClientRect();this.scale=Math.min(r.width/700,r.height/950);this.ox=r.width/2-450*this.scale;this.oy=r.height/2-475*this.scale;this.stage.draw(this);return;}const c=this.ctx,r=this.canvas.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,2);if(this.canvas.width!==Math.round(r.width*dpr)||this.canvas.height!==Math.round(r.height*dpr)){this.canvas.width=Math.round(r.width*dpr);this.canvas.height=Math.round(r.height*dpr);}c.setTransform(dpr,0,0,dpr,0,0);const bg=c.createLinearGradient(0,0,0,r.height);bg.addColorStop(0,['meal','prostrate','sermon'].includes(this.id)?'#5b3e29':'#285e51');bg.addColorStop(1,'#172e29');c.fillStyle=bg;c.fillRect(0,0,r.width,r.height);this.scale=Math.min(r.width/700,r.height/950);this.ox=r.width/2-450*this.scale;this.oy=r.height/2-475*this.scale;c.save();c.translate(this.ox,this.oy);c.scale(this.scale,this.scale);const s=this.scene,t=s.time,age=t-this.lastHit,hit=Math.max(0,1-age/.65),rule=activityRules[this.id];s.ellipse(450,670,290,70,'#102f2940');s.ellipse(450,470,330,300,'#fff3bc08');
 if(this.id==='beads'){const drag=Math.max(-40,Math.min(70,this.drag||0));for(let i=0;i<18;i++){const a=i*Math.PI/9+s.task.rotation+drag/300,x=450+Math.cos(a)*230,y=430+Math.sin(a)*250;s.ellipse(x+4,y+9,23,24,'#152c27aa');s.ellipse(x,y,23,24,i===s.task.count%18?'#f2ce7f':'#b17b42','#f0ca7b');s.ellipse(x-7,y-7,5,5,'#f4d6a37a');}s.line(450,680,450,730,'#dbac66',6);s.text('✦',450,750,38,'#f0c67b');s.text('↓',450,425+Math.sin(t*2)*12,72,'#f4dca8');}
 else if(this.id==='chant'){c.save();c.translate(450,475);c.scale(4,4);s.ellipse(0,20,39,12,'#122b2555');s.ellipse(0,0,40+hit*2,27-hit*3,'#c98b48','#edc17c');s.path([[-26,-10],[-8,-18],[11,-13],[24,-3]],null,'#e9b365',3);s.path([[-14,-7],[-4,0],[12,4]],null,'#754729',4);s.line(44,-58-hit*9,14,-18+hit*20,'#ae7b46',7);s.ellipse(14,-18+hit*20,9,7,'#ddb277');c.restore();for(let i=0;i<3;i++)if(hit>0)s.text('♪',340+i*100,330-age*65,26+hit*9,'#f4da8c');s.text(['Nam mô A Di Đà Phật','Tâm an, lời nói hiền','Gieo một điều tử tế','Nguyện mọi người bình an'][s.task.count%4],450,200,30,'#f6e6ba');}
 else if(this.id==='incense'){c.save();c.translate(450,515);c.scale(3,3);c.translate(-450,-635);s.burner();c.restore();s.stick(450,410-hit*60,110,true);s.text('↑',450,260-Math.sin(t*2)*10,65,'#f4dca8');}
 else if(this.id==='fish'){c.save();c.translate(450,470);c.scale(1.85,2.1);c.translate(-725,-880);s.pond();c.restore();if(hit>0)s.text('🐟',450+Math.sin(age*5)*60,280+age*220,54,'#fff3bb');s.text('↓',450,220+Math.sin(t*2)*8,65,'#f4dca8');}
 else if(this.id==='sweep'){for(let i=0;i<9;i++){const x=220+(i%3)*220,y=300+Math.floor(i/3)*130;if(i===s.task.count%9&&hit>0)continue;c.save();c.translate(x+hit*60*Math.sin(i),y);c.rotate(i+t*.05);s.path([[-25,0],[0,-13],[30,0],[0,13]],'#e5ac57');s.line(-20,0,25,0,'#b7793d',2);c.restore();}const x=440+hit*140;c.save();c.translate(x,470);c.rotate(-.6+hit*.5);s.line(0,-180,0,60,'#ab7c48',15);s.path([[-20,45],[20,45],[55,120],[-55,120]],'#eec46f');for(let i=-3;i<=3;i++)s.line(i*6,60,i*14,115,'#be8c46',3);c.restore();}
 else if(this.id==='meal'){s.rounded(210,310,480,280,35,'#9c633c','#c69a5d');s.ellipse(450,470,145,78,'#dbd5be');s.ellipse(450,445,140,66,'#f8efd6');s.ellipse(450,440,110,44,'#fff9e8');for(let i=0;i<22;i++)s.line(365+(i*31)%175,415+(i*19)%50,373+(i*31)%175,415+(i*19)%50,'#ded9b9',3);s.ellipse(300,345,70,34,'#e8d9ba');s.ellipse(300,340,55,25,'#8cae61');s.ellipse(600,355,65,31,'#f1e0be');s.ellipse(600,350,48,23,'#dbaa65');s.line(610,530,520-hit*30,340-hit*90,'#775137',9);s.line(630,528,540-hit*30,340-hit*90,'#775137',9);}
 else {s.ellipse(450,520,160,65,'#c0945c','#e5bf7e');s.ellipse(450,510,140,50,'#ddb075');const breathe=(Math.sin(t*Math.PI/4)+1)/2;s.ellipse(450,510,170+breathe*45,70+breathe*15,'#ffe4a017');if(this.id==='prostrate'){s.text('☸',450,220,110,'#e6c276');s.text('Nhẹ thân · Thành tâm',450,330,27,'#ebd5a2');}else s.text(breathe>.5?'Hít vào thật nhẹ…':'Thở ra thật chậm…',450,270,31,'#eadbb6');}
 const action=this.id==='prostrate'?(age<2.4?'prostrate':'idle'):rule.action;s.character({...this.player,x:450,y:850,name:'',preview:true,action,animationStarted:this.lastHit<0?0:Date.now()-age*1000},false);if(hit>0)s.text('+1',650,700-age*80,40,'#ffe19b');c.restore();}
}
